#define MAX 5
typedef struct {
    int items[MAX];
    int front, rear, size;
} Queue;

int enqueue(Queue* q, int value) {
    if (q->size == MAX) return 0; // overflow
    q->items[q->rear] = value;
    q->rear = (q->rear + 1) % MAX;
    q->size++;
    return 1;
}

int dequeue(Queue* q, int* out) {
    if (q->size == 0) return 0; // underflow
    *out = q->items[q->front];
    q->front = (q->front + 1) % MAX;
    q->size--;
    return 1;
}

